  $j$[]$j$::jsonb, $j$[{"clave":"principal_marca","etiqueta":"Principal · Marca","tipo":"texto","obligatorio":true},{"clave":"principal_potencia","etiqueta":"Principal · Potencia","tipo":"texto","obligatorio":true},{"clave":"principal_caudal","etiqueta":"Principal · Caudal","tipo":"texto","obligatorio":true},{"clave":"principal_presion_nominal","etiqueta":"Principal · Presión nominal","tipo":"texto","obligatorio":true},{"clave":"principal_arranque_parada","etiqueta":"Principal · Arranque / Parada","tipo":"texto","obligatorio":true},{"clave":"principal_alimentacion","etiqueta":"Principal · Alimentación / Observación","tipo":"texto","obligatorio":true},{"clave":"jockey_marca","etiqueta":"Jockey · Marca","tipo":"texto","obligatorio":true},{"clave":"jockey_potencia","etiqueta":"Jockey · Potencia","tipo":"texto","obligatorio":true},{"clave":"jockey_caudal","etiqueta":"Jockey · Caudal","tipo":"texto","obligatorio":true},{"clave":"jockey_presion_nominal","etiqueta":"Jockey · Presión nominal","tipo":"texto","obligatorio":true},{"clave":"jockey_arranque_parada","etiqueta":"Jockey · Arranque / Parada","tipo":"texto","obligatorio":true},{"clave":"jockey_alimentacion","etiqueta":"Jockey · Alimentación / Observación","tipo":"texto","obligatorio":true}]$j$::jsonb, false);
with p as (insert into public.plantillas (codigo, nombre, descripcion, aplica_a, tipo_activo_id, frecuencia)
  values ('electrobomba', 'Inspección de electrobomba', '1 inspección = 1 electrobomba, cada semana. 29 puntos Sí / No (13 antes, 9 durante y 7 después de la prueba) y la prueba funcional (antes y final). Parte de «Inspección de bomba contra incendio».', 'activo', (select id from public.tipos_activo where empresa_id is null and codigo = 'electrobomba'), 'semanal') returning id),
r as (select $j${"version":1,"firmas":[{"clave":"inspector","titulo":"Inspector","obligatoria":true,"externo":false,"minimo":1},{"clave":"custodia","titulo":"Responsable de la custodia del registro","obligatoria":true,"externo":false,"minimo":1}],"reglas":[{"tipo":"x_en","etiqueta":"No conforme","alcance":"todos"}],"resultado_defecto":"Conforme","puntaje":false,"na_favorable":true,"hallazgo_vencimiento":false,"observacion_general":true,"secciones":[{"clave":"antes","titulo":"ANTES DE LA PRUEBA","puntos":[{"clave":"EB-A01","texto":"Acceso al cuarto de bombas libre, señalizado y sin obstrucciones.","tipo":"si_no","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":true,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"EB-A02","texto":"Cuarto de bombas limpio, ordenado y sin almacenamiento de materiales ajenos al sistema.","tipo":"si_no","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":true,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"EB-A03","texto":"No se evidencian filtraciones, inundación o acumulación de agua","tipo":"si_no","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":true,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"EB-A04","texto":"Iluminación del cuarto de bombas operativa","tipo":"si_no","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":true,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"EB-A05","texto":"Tuberías, accesorios, soportes y uniones sin daños visibles ni corrosión crítica.","tipo":"si_no","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":true,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"EB-A06","texto":"Válvulas asociadas a la bomba Jockey en posición normal de operación.","tipo":"si_no","obligatorio":true,"critico":false,"hallazgo":"nunca","obs_si_no_cumple":true,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"EB-A07","texto":"Manómetro de la bomba principal en buen es